var EpisodeCrawler = class extends EventEmitter5 {
  limiter;
  list;
  done = false;
  results = [];
  constructor(list = [], limiter = new RateLimiter()) {
    super();
    this.list = list;
    this.limiter = limiter;
  }
  async crawl() {
    if (this.done) {
      return this.results;
    }
    let total = this.list.length;
    let current = 0;
    this.results = [];
    const tasks = [];
    for (const { ref, episodes } of this.list) {
      const pairs = Object.entries(episodes);
      total += pairs.length - 1;
      for (const [name, serial] of pairs) {
        tasks.push(
          (async () => {
            await retry(async () => {
              await this.limiter.lock();
              try {
                const $ = cheerio2.load(
                  await fetch4(
                    `https://ani.gamer.com.tw/animeVideo.php?sn=${serial}`
                  ).then((res) => res.text())
                );
                const view = normalize_number($(".newanime-count > span").text());
                this.results.push({ ref, name, serial, view });
              } finally {
                this.limiter.unlock();
              }
            }).catch((err) => this.emit("error", err));
            this.emit("progress", ++current, total);
          })()
        );
      }
    }
    await Promise.all(tasks);
    this.results.sort((a, b) => a.serial - b.serial);
    this.done = true;
    this.emit("done", this.results);
    return this.results;
  }
  on(event, listener) {
    return super.on(event, listener);
  }
};

